INSERT INTO `cp_itemdesc` VALUES
(501,'A potion made from grinded Red Herbs.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 45 - 65</font> HP<br />Weight:<font color=\'#009900\'> 7</font>'),
(502,'A potion made from grinded Red and Yellow Herbs.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 105 - 145</font> HP<br />Weight:<font color=\'#009900\'> 10</font>'),
(503,'A potion made from grinded Yellow Herbs.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 175 - 235</font> HP<br />Weight:<font color=\'#009900\'> 13</font>'),
(504,'A potion made from grinded White Herbs.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br />Weight:<font color=\'#009900\'> 15</font>'),
(505,'A potion made from grinded Blue Herbs.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 40 - 60</font> SP<br />Weight:<font color=\'#009900\'> 15</font>'),
(506,'A potion made from grinded Green Herbs.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Cure:<font color=\'#009900\'> Poison, Silence, Blind, Confuse, Illusion</font><br />Weight:<font color=\'#009900\'> 7</font>'),
(507,'A weak medicinal herb which heals wounds.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 18 - 28</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(508,'A valuable medicinal herb which efficiently heals wounds.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 38 - 58</font> HP<br />Weight:<font color=\'#009900\'> 5</font>'),
(509,'A valuable medicinal herb which greatly heals wounds.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 75 - 115</font> HP<br />Weight:<font color=\'#009900\'> 7</font>'),
(510,'A very valuable medicinal herb whose unique aroma gratifies one\'s spirit.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 15 - 30</font> SP<br />Weight:<font color=\'#009900\'> 7</font>'),
(511,'A precious medicinal herb that counteracts all poison.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Cure:<font color=\'#009900\'> Poison</font><br />Weight:<font color=\'#009900\'> 3</font>'),
(512,'A round, edible fruit that, when eaten once a day, keeps the doctor away.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 16 - 22</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(513,'A sweet tasting tropical fruit made famous by its use in slapstick comedy and practical jokes.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 17 - 21</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(514,'Clustered berries with smooth skin that can be fermented to make wine.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 10 - 15</font> SP<br />Weight:<font color=\'#009900\'> 2</font>'),
(515,'An orange root that is supposedly good for your vision. Despite the Beta Carotene, kids don\'t care much for it.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 18 - 20</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(516,'A tuber that can be fried, baked, boiled mashed, even eaten.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 15 - 23</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(517,'A leg of meat that\'s been cooked to near perfection.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 70 - 100</font> HP<br />Weight:<font color=\'#009900\'> 15</font>'),
(518,'A sweet product made by bees that is endowed with yummy flavor and medicinal uses.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 70 - 100</font> HP<br /><font color=\'#009900\'>20 - 40</font> SP<br />Weight:<font color=\'#009900\'> 10</font>'),
(519,'Pasteurized and bottled cow milk that is chock full of bovine goodness.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 27 - 37</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(520,'Leaf cut from a Hinalle Plant which has a cool, fresh scent. It can ease pain and reinvigorate.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 175 - 235</font> HP<br />Weight:<font color=\'#009900\'> 1</font>'),
(521,'Leaf cut from an Aloe plant.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(522,'A shiny, purple fruit picked from the boughs of the Mastela tree.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 400 - 600</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(523,'Blessed water used in sacred ceremonies.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Cure:<font color=\'#009900\'> Curse</font><br />Weight:<font color=\'#009900\'> 3</font>'),
(525,'A mystic remedy for all illnesses.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Cure:<font color=\'#009900\'> Poison, Curse, Silence, Confusion, Blind</font><br />Weight:<font color=\'#009900\'> 10</font>'),
(526,'Highly nutritious jelly secreted from honeybees that they only feed to larvas and future queens.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br /><font color=\'#009900\'>40 - 60</font> SP<br />Cure:<font color=\'#009900\'> Poison, Curse, Silence, Confusion, Blind</font><br />Weight:<font color=\'#009900\'> 15</font>'),
(528,'Processed food that is normally fed to monsters.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 72 - 108</font> HP<br />Weight:<font color=\'#009900\'> 15</font>'),
(529,'A confection of sugar, chocolate and other flavorings. Kids love it!<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 45 - 65</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(530,'A striped cane of peppermint candy. Sugar daddies love it!<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 105 - 145</font> HP<br />Weight:<font color=\'#009900\'> 4</font>'),
(531,'Bottled apple juice that\'s easy to digest.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 25 - 35</font> HP<br />Weight:<font color=\'#009900\'> 4</font>'),
(532,'Bottled banana juice that\'s easy to digest.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 26 - 34</font> HP<br />Weight:<font color=\'#009900\'> 4</font>'),
(533,'Bottled grape juice that\'s easy to digest.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 15 - 25</font> SP<br />Weight:<font color=\'#009900\'> 4</font>'),
(534,'Bottled carrot juice that\'s easy to digest.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 27 - 33</font> HP<br />Weight:<font color=\'#009900\'> 4</font>'),
(535,'A large orange fruit grown from a vine that\'s used in baking pies and a few other dishes.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 19</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(536,'Deliciously frosty ice cream that can cause brain freeze if you eat too much too quickly.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 105 - 145</font> HP<br />Weight:<font color=\'#009900\'> 8</font>'),
(537,'Sterilized food that has been fortified with vitamins and minerals. Some Cute Pets will feed on this.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 50 - 90</font> HP<br />Weight:<font color=\'#009900\'> 1</font>'),
(538,'A warm, scrumptious cookie.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 160 - 200</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(539,'A sweet slice of cake covered in icing and topped with a cherry.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 270 - 330</font> HP<br />Weight:<font color=\'#009900\'> 10</font>'),
(540,'Food intended for Falcons, but it\'s actually tasty enough for humans to eat.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 185 - 225</font> HP<br />Weight:<font color=\'#009900\'> 5</font>'),
(541,'Food manufactured to feed Peco Pecos, but will suffice for desperately hungry humans as well.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br />Weight:<font color=\'#009900\'> 5</font>'),
(542,'A sweet and crunchy snack usually available during certain times in Japan.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br />Weight:<font color=\'#009900\'> 7</font>'),
(543,'Cake made of rice decorated in 3 colors, red, white and green.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br />Weight:<font color=\'#009900\'> 7</font>'),
(544,'A raw, fresh fish.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 25 - 60</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(545,'A condensed Red Potion that weighs significantly less.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 45 - 65</font> HP<br />Weight:<font color=\'#009900\'> 1</font>'),
(546,'A condensed yellow potion that weighs significantly less.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 175 - 235</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(547,'A condensed white potion that weighs significantly less.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 325 - 405</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(548,'A palatable food with a unique scent.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 10 - 15</font> SP<br />Weight:<font color=\'#009900\'> 5</font>'),
(549,'A kind of plant root used as food. It\'s advised to eat this slowly with water, or to bake it beforehand.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 50 - 100</font> HP<br />Weight:<font color=\'#009900\'> 8</font>'),
(550,'A snack made out of rice that doesn\'t contain any fat. Some women love having this snack.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 10 - 15</font> HP<br />Weight:<font color=\'#009900\'> 1</font>'),
(551,'An Eastern delicacy, in which various types of raw fish is placed on top of rice.<br />The rice is marinated in vinegar then wrapped in dried seaweed.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 50 - 60</font> HP<br />Weight:<font color=\'#009900\'> 5</font>'),
(552,'A type of food that is usually eaten by people in a country after their abstinence ceremony.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 70 - 90</font> HP<br /><font color=\'#009900\'>20 - 30</font> SP<br />Weight:<font color=\'#009900\'> 1</font>'),
(553,'A type of dough that is filled with ground meat, usually served hot.<br />People living in eastern countries have enjoyed eating this food for a long time.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 35 - 70</font> HP<br />Weight:<font color=\'#009900\'> 5</font>'),
(554,'A tasty rice cake made for celebrating the Lunar New Year.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 105 - 145</font> HP<br />Weight:<font color=\'#009900\'> 8</font>'),
(555,'A type of food that is made of rice powder. There are many recipes to make this food, all of them absolutely delicious.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 105 - 145</font> HP<br />Weight:<font color=\'#009900\'> 2</font>'),
(556,'A thin stick of rice cake which is moist and sticky.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 20 - 25</font> HP<br />Weight:<font color=\'#009900\'> 1</font>'),
(557,'A bag of sliced rice cake. Can be cooked in various ways.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 25 - 30</font> HP<br />Weight:<font color=\'#009900\'> 1</font>'),
(558,'Fried and grinded Cacao that is solidified with Milk and cacao paste. Delicious and bittersweet.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 1</font> HP, <font color=\'#009900\'>1</font> SP<br />Weight:<font color=\'#009900\'> 2</font>'),
(559,'A collection of chocolates that are gathered and arranged to make a beautiful item. This is often used in courtship, and sometimes even used effectively.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 50</font> HP, <font color=\'#009900\'>50</font> SP<br />Weight:<font color=\'#009900\'> 8</font>'),
(560,'White chocolate which is used to propose to a girl by a boy during White Day.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 50</font> HP, <font color=\'#009900\'>50</font> SP<br />Weight:<font color=\'#009900\'> 8</font>'),
(561,'A white cacao.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 50</font> HP, <font color=\'#009900\'>50</font> SP<br />Weight:<font color=\'#009900\'> 8</font>'),
(562,'A cheese that was put in between bread with sauces and other stuff before it was added with sweet potatoes and butter to be make into Domino Swiss Pizza.<br />It taste soft and sweet as if it melted in your mouth. This is the double layered Pizza made by Domino, the high quality pizza maker.<br />[To be sent]<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 70 - 100</font> HP<br />Weight:<font color=\'#009900\'> 15</font>'),
(563,'A cheese that was put in between bread with sauces and other stuff before it was added with sweet potatoes and butter to be make into Domino Swiss Pizza.<br />It taste soft and sweet as if it melted in your mouth. This is the double layered Pizza made by Domino, the high quality pizza maker.<br />[To be sent]<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 375 - 445</font> HP<br />Weight:<font color=\'#009900\'> 15</font>'),
(564,'A lump of rice which can be eaten for lunch.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 200</font> HP<br />Weight:<font color=\'#009900\'> 3</font>'),
(565,'A delicious multi-vitamin drink. It is without caffeine and good for your health.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 142 - 274</font> HP<br />Weight:<font color=\'#009900\'> 10</font>'),
(566,'A type of soup which is regarded as one of the three famous soups in the world.<br />It has a spicy, sweet and sour taste with shrimps, lemons and chilies.<br /><font color=\'#FFFFFF\'>_</font><br />Class:<font color=\'#0000FF\'> Restorative</font><br />Heal:<font color=\'#009900\'> 244 - 350</font> HP,<br /><font color=\'#009900\'>10 - 30</font> SP<br />Cure:<font color=\'#009900\'> Poison, Silence, Blind, Confusion, Curse</font><br />Weight:<font color=\'#009900\'> 15</font>'),
