(101115,'Summons 500 Hamaya Kunais.<br /><font color=\'#FFFFFF\'>_</font><br /><font color=\'#0000CC\'>Weight:</font> 25'),
(1220002,'A Kunai with the energy of air. You can feel the power to cut through air easily.<br /><font color=\'#FFFFFF\'>_</font><br /><font color=\'#0000CC\'>Type:</font> Kunai<br /><font color=\'#0000CC\'>Attack:</font> 30<br /><font color=\'#0000CC\'>Weight:</font> 0.1<br /><font color=\'#0000CC\'>Element:</font><font color=\'#777777\'> Neutral</font>'),
